parameters.jsCode:
const kpi = $('KPI generate').first().json;
let llmText = '';
try { llmText = $('Basic LLM Chain').first().json.text || ''; }
catch (e) { llmText = $input.first().json.text || ''; }

const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const inline = s => esc(s)
  .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
  .replace(/\*(.+?)\*/g, '<em>$1</em>');

// LLM markdown text -> HTML
function mdToHtml(md) {
  let html = '', list = null;
  const close = () => { if (list) { html += `</${list}>`; list = null; } };
  for (const raw of md.replace(/\r/g, '').split('\n')) {
    const line = raw.trim();
    if (!line) { close(); continue; }
    let m;
    if ((m = line.match(/^#{1,6}\s*(.+)$/))) {
      close();
      html += `<h3 style="color:#1f3a5f;margin:18px 0 8px;font-size:17px;">${inline(m[1])}</h3>`;
    } else if ((m = line.match(/^\d+\.\s+(.+)$/))) {
      if (list !== 'ol') { close(); html += '<ol style="padding-left:20px;margin:6px 0;">'; list = 'ol'; }
      html += `<li style="margin-bottom:8px;line-height:1.5;">${inline(m[1])}</li>`;
    } else if ((m = line.match(/^[-*•]\s+(.+)$/))) {
      if (list !== 'ul') { close(); html += '<ul style="padding-left:20px;margin:6px 0;">'; list = 'ul'; }
      html += `<li style="margin-bottom:8px;line-height:1.5;">${inline(m[1])}</li>`;
    } else {
      close();
      html += `<p style="margin:8px 0;line-height:1.6;">${inline(line)}</p>`;
    }
  }
  close();
  return html;
}

// ---- Auto executive summary (data se) ----
const gap = Math.round((kpi.Avg_Attendance_Percentage - kpi.Avg_Assignment_Completion_Rate) * 10) / 10;
const topCities = (kpi.Student_Count_By_City || []).slice(0, 3)
  .map(c => `${esc(c.City)} (${c.Count})`).join(', ');
const summaryPoints = [
  `The dataset covers <strong>${kpi.Total_Students}</strong> students with an average engagement score of <strong>${kpi.Avg_Engagement_Score}/100</strong>.`,
  `Average attendance is <strong>${kpi.Avg_Attendance_Percentage}%</strong>, but assignment completion is only <strong>${kpi.Avg_Assignment_Completion_Rate}%</strong>, a gap of <strong>${gap} points</strong>.`,
  `<strong>${kpi.High_Dropout_Risk_Percent}%</strong> of students are at high dropout risk and <strong>${kpi.Low_Engagement_Percent}%</strong> have low engagement.`,
  `The pass percentage (grades A to D) is <strong>${kpi.Pass_Percentage}%</strong>.`,
  `Top locations by student count: ${topCities}.`
];

// ---- KPI cards ----
const cards = [
  ['Total Students', kpi.Total_Students, ''],
  ['Avg Engagement Score', kpi.Avg_Engagement_Score, '/100'],
  ['Avg Attendance', kpi.Avg_Attendance_Percentage, '%'],
  ['Avg Assignment Completion', kpi.Avg_Assignment_Completion_Rate, '%'],
  ['Avg Quiz Score', kpi.Avg_Quiz_Score, '%'],
  ['High Dropout Risk', kpi.High_Dropout_Risk_Percent, '%'],
  ['Low Engagement', kpi.Low_Engagement_Percent, '%'],
  ['Pass Percentage', kpi.Pass_Percentage, '%']
];
const cardCell = ([label, val, suffix]) => `
  <td style="width:25%;padding:6px;">
    <div style="background:#f0f5fb;border-radius:8px;padding:14px 8px;text-align:center;">
      <div style="font-size:22px;font-weight:bold;color:#1f3a5f;">${val}${suffix}</div>
      <div style="font-size:12px;color:#5b6b7f;margin-top:4px;">${label}</div>
    </div>
  </td>`;
const cardsHtml = `<table width="100%" cellspacing="0" cellpadding="0">
  <tr>${cards.slice(0, 4).map(cardCell).join('')}</tr>
  <tr>${cards.slice(4).map(cardCell).join('')}</tr></table>`;

// ---- Distribution tables ----
const total = kpi.Total_Students;
const distTable = (title, obj) => `
  <table width="48%" cellspacing="0" cellpadding="8" style="display:inline-table;vertical-align:top;border-collapse:collapse;margin:6px 1%;">
    <tr style="background:#1f3a5f;color:#fff;"><th align="left">${title}</th><th align="right">Students</th><th align="right">%</th></tr>
    ${Object.entries(obj).map(([k, v]) => `
    <tr style="border-bottom:1px solid #e3e8ef;"><td>${k}</td><td align="right">${v}</td><td align="right">${Math.round((v / total) * 1000) / 10}%</td></tr>`).join('')}
  </table>`;

const date = new Date().toLocaleDateString('en-IN', { day: 'numeric', month: 'long', year: 'numeric' });

const html = `<!DOCTYPE html>
<html><head><meta charset="utf-8"><title>Student Engagement Report</title></head>
<body style="margin:0;background:#eef2f7;font-family:Arial,Helvetica,sans-serif;color:#2b3a4a;">
<div style="max-width:820px;margin:20px auto;background:#ffffff;border-radius:10px;overflow:hidden;">
  <div style="background:#1f3a5f;color:#fff;padding:24px 28px;">
    <h1 style="margin:0;font-size:24px;">Student Engagement Report</h1>
    <div style="font-size:13px;margin-top:6px;opacity:0.85;">Generated automatically on ${date}</div>
  </div>
  <div style="padding:24px 28px;">
    <h2 style="color:#1f3a5f;font-size:19px;margin:0 0 10px;">Executive Summary</h2>
    <ul style="padding-left:20px;line-height:1.6;margin:0 0 20px;">
      ${summaryPoints.map(p => `<li style="margin-bottom:6px;">${p}</li>`).join('')}
    </ul>

    <h2 style="color:#1f3a5f;font-size:19px;margin:24px 0 10px;">Key Performance Indicators</h2>
    ${cardsHtml}

    <h2 style="color:#1f3a5f;font-size:19px;margin:24px 0 10px;">Distributions</h2>
    ${distTable('Engagement Level', kpi.Engagement_Level_Distribution)}
    ${distTable('Dropout Risk', kpi.Dropout_Risk_Distribution)}

    <h2 style="color:#1f3a5f;font-size:19px;margin:24px 0 10px;">Charts</h2>
    <img src="${kpi.Chart_URL}" alt="Student Count by Location" style="max-width:100%;border:1px solid #e3e8ef;border-radius:6px;margin-bottom:16px;">
    <img src="${kpi.Chart_URL_2}" alt="Dropout Risk by Engagement Level" style="max-width:100%;border:1px solid #e3e8ef;border-radius:6px;">

    <h2 style="color:#1f3a5f;font-size:19px;margin:28px 0 10px;">AI Insights and Recommendations</h2>
    <div style="background:#f9fbfd;border-left:4px solid #1f3a5f;padding:6px 16px;">
      ${mdToHtml(llmText)}
    </div>
  </div>
  <div style="background:#f0f5fb;padding:14px 28px;font-size:12px;color:#5b6b7f;">
    Report generated by an n8n automation workflow. Data source: Student Engagement Dataset.
  </div>
</div>
</body></html>`;

return [{
  json: { html, subject: `Student Engagement Report - ${date}` },
  binary: $input.first().binary || {}
}];

const isBlank = v => v === undefined || v === null || String(v).trim() === '';

const numCols = ['Age','Semester','Attendance_Percentage','Login_Frequency_Per_Week','Video_Watch_Hours','Assignment_Completion_Rate','Quiz_Attempts','Quiz_Average_Score','Discussion_Forum_Posts','Study_Hours_Per_Week','Last_Login_Days_Ago'];
const textCols = ['Student_Name','Gender','Course','Department','Final_Grade','Enrollment_Date','City','Learning_Mode'];

// 1. Duplicate Student_ID 
const seen = new Set();
let rows = $input.all().map(i => i.json).filter(r => {
  if (seen.has(r.Student_ID)) return false;
  seen.add(r.Student_ID);
  return true;
});

// 2. Trim + numbers convert + missing count
rows = rows.map(r => {
  const o = { ...r };
  let missing = 0;
  for (const k of Object.keys(o)) if (typeof o[k] === 'string') o[k] = o[k].trim();
  for (const c of numCols) {
    if (isBlank(o[c]) || isNaN(Number(o[c]))) { o[c] = null; missing++; }
    else o[c] = Number(o[c]);
  }
  for (const c of [...textCols, 'Engagement_Score', 'Engagement_Level', 'Dropout_Risk']) {
    if (isBlank(o[c])) missing++;
  }
  o.Missing_Fields_Count = missing;
  return o;
});


const median = arr => {
  const a = arr.filter(v => v !== null).sort((x, y) => x - y);
  const m = Math.floor(a.length / 2);
  return a.length % 2 ? a[m] : (a[m - 1] + a[m]) / 2;
};
const med = {};
numCols.forEach(c => med[c] = median(rows.map(r => r[c])));

const clamp = (v, a, b) => Math.min(b, Math.max(a, v));

rows = rows.map(o => {
  for (const c of numCols) if (o[c] === null) o[c] = med[c];


  o.Age = clamp(Math.round(o.Age), 18, 25);
  o.Semester = clamp(Math.round(o.Semester), 1, 8);
  o.Attendance_Percentage = clamp(o.Attendance_Percentage, 50, 100);
  o.Assignment_Completion_Rate = clamp(o.Assignment_Completion_Rate, 0, 100);
  o.Quiz_Average_Score = clamp(o.Quiz_Average_Score, 0, 100);
  o.Study_Hours_Per_Week = clamp(o.Study_Hours_Per_Week, 0, 40);


  for (const c of textCols) if (isBlank(o[c])) o[c] = 'Unknown';


  if (isBlank(o.Engagement_Score)) {
    const s = 100 * (
      0.20 * (o.Attendance_Percentage - 50) / 50 +
      0.15 * Math.min(o.Login_Frequency_Per_Week / 10, 1) +
      0.15 * Math.min(o.Video_Watch_Hours / 10, 1) +
      0.20 * o.Assignment_Completion_Rate / 100 +
      0.20 * o.Quiz_Average_Score / 100 +
      0.10 * Math.min(o.Discussion_Forum_Posts / 15, 1)
    );
    o.Engagement_Score = Math.round(clamp(s, 0, 100) * 10) / 10;
  } else {
    o.Engagement_Score = Number(o.Engagement_Score);
  }


  o.Engagement_Level = o.Engagement_Score < 40 ? 'Low' : o.Engagement_Score < 70 ? 'Medium' : 'High';


  if (isBlank(o.Dropout_Risk)) {
    const r = 0.35 * (1 - o.Engagement_Score / 100) +
              0.20 * (1 - (o.Attendance_Percentage - 50) / 50) +
              0.20 * (1 - o.Assignment_Completion_Rate / 100) +
              0.25 * Math.min(o.Last_Login_Days_Ago / 30, 1);
    o.Dropout_Risk = r >= 0.52 ? 'High' : r >= 0.30 ? 'Medium' : 'Low';
  }
  return o;
});

return rows.map(r => ({ json: r }));

const rows = $input.all().map(i => i.json);
const total = rows.length;

const avg = k => {
  const v = rows.map(r => Number(r[k])).filter(x => !isNaN(x));
  return v.length ? v.reduce((a, b) => a + b, 0) / v.length : 0;
};
const r1 = x => Math.round(x * 10) / 10;
const count = (k, val) => rows.filter(r => r[k] === val).length;
const pct = n => r1((n / total) * 100);

// ---- 8 KPIs ----
const kpis = {
  Total_Students: total,
  Avg_Engagement_Score: r1(avg('Engagement_Score')),
  Avg_Attendance_Percentage: r1(avg('Attendance_Percentage')),
  Avg_Assignment_Completion_Rate: r1(avg('Assignment_Completion_Rate')),
  Avg_Quiz_Score: r1(avg('Quiz_Average_Score')),
  High_Dropout_Risk_Percent: pct(count('Dropout_Risk', 'High')),
  Low_Engagement_Percent: pct(count('Engagement_Level', 'Low')),
  Pass_Percentage: pct(rows.filter(r => ['A', 'B', 'C', 'D'].includes(r.Final_Grade)).length)
};

// ---- Distributions ----
const dist = (k, values) => Object.fromEntries(values.map(v => [v, count(k, v)]));
const engagementDist = dist('Engagement_Level', ['Low', 'Medium', 'High']);
const dropoutDist = dist('Dropout_Risk', ['Low', 'Medium', 'High']);

// ---- Chart 1: Student count by location ----
const cityMap = {};
rows.forEach(r => {
  const c = r.City || 'Unknown';
  cityMap[c] = (cityMap[c] || 0) + 1;
});
const cityCounts = Object.entries(cityMap)
  .map(([City, Count]) => ({ City, Count }))
  .sort((a, b) => b.Count - a.Count);

const chartConfig = {
  type: 'horizontalBar',
  data: {
    labels: cityCounts.map(c => c.City),
    datasets: [{
      label: 'Students',
      data: cityCounts.map(c => c.Count),
      backgroundColor: 'rgba(54, 162, 235, 0.7)'
    }]
  },
  options: {
    title: { display: true, text: 'Student Count by Location' },
    legend: { display: false },
    scales: { xAxes: [{ ticks: { beginAtZero: true } }] }
  }
};
const Chart_URL = 'https://quickchart.io/chart?w=800&h=700&c=' +
  encodeURIComponent(JSON.stringify(chartConfig));

// ---- Chart 2: Dropout Risk by Engagement Level ----
const levels = ['Low', 'Medium', 'High'];
const risks = ['Low', 'Medium', 'High'];
const colors = { Low: 'rgba(75,192,120,0.8)', Medium: 'rgba(255,193,7,0.8)', High: 'rgba(255,99,132,0.8)' };

const chartConfig2 = {
  type: 'bar',
  data: {
    labels: levels.map(l => l + ' Engagement'),
    datasets: risks.map(rk => ({
      label: rk + ' Dropout Risk',
      backgroundColor: colors[rk],
      data: levels.map(l => rows.filter(r => r.Engagement_Level === l && r.Dropout_Risk === rk).length)
    }))
  },
  options: {
    title: { display: true, text: 'Dropout Risk by Engagement Level' },
    scales: { yAxes: [{ ticks: { beginAtZero: true } }] }
  }
};
const Chart_URL_2 = 'https://quickchart.io/chart?w=800&h=500&c=' +
  encodeURIComponent(JSON.stringify(chartConfig2));

return [{
  json: {
    ...kpis,
    Engagement_Level_Distribution: engagementDist,
    Dropout_Risk_Distribution: dropoutDist,
    Student_Count_By_City: cityCounts,
    Chart_URL,
    Chart_URL_2
  }
}];
